/** Isolated owned SQL/transaction/lease faults. The A port here is explicitly controlled. */
public final class ReconciliationCommands {
 private static final ObjectMapper JSON=new ObjectMapper();private static String id(){return UUID.randomUUID().toString();}
 @Configuration(proxyBeanMethods=false) public static class Config {@Bean @Primary PaymentClosingCommands.Probe reconciliationTradeProbe(){return new PaymentClosingCommands.Probe();}}
 public static final class Probe implements IReconciliationPort {
  final PaymentClosingCommands.Probe trades;final Map<String,String> states=new HashMap<>();final Map<String,Roster> rosters=new HashMap<>();final Map<String,Paid> paid=new HashMap<>();final Map<String,Completion> completed=new HashMap<>();boolean lost,offline;int completeCalls;
  Probe(PaymentClosingCommands.Probe trades){this.trades=trades;}
  private ReservationEvidence first(String team){return trades.delegate.records.values().stream().filter(e->team.equals(e.teamId())).findFirst().orElseThrow();}
  public Team team(String team){check(!TransactionSynchronizationManager.isActualTransactionActive(),"reconciliation network outside marketplace tx");if(offline)throw new IllegalStateException("owned A outage");var e=first(team);String status=states.getOrDefault(team,"RECONCILING");return new Team(team,status,status.equals("RECONCILING")?"3":"9",e.goodsId(),e.activityId(),e.paymentDeadline(),PaymentService.time(System.currentTimeMillis()));}
  public Roster roster(String team){return rosters.computeIfAbsent(team,key->{var members=new ArrayList<Member>();for(var e:trades.delegate.records.values())if(team.equals(e.teamId()))members.add(new Member(e.userId(),e.outTradeNo(),e.orderId(),paid.containsKey(e.outTradeNo())?"PAID":e.orderStatus(),e.reservedAt(),e.paymentDeadline(),e.payPrice(),e.currency(),paid.get(e.outTradeNo())));return new Roster(id(),id(),team(team).status(),team(team).version(),first(team).paymentDeadline(),members);});}
  public Trade trade(MarketOrder order){var e=trades.execute(new TradeDispatch(null,order,"query",id(),null)).evidence();e=CloseCommands.change(e,"teamStatus",team(e.teamId()).status());e=CloseCommands.change(e,"teamVersion",team(e.teamId()).version());var p=paid.get(order.orderId());if(p!=null){e=CloseCommands.change(e,"orderStatus","PAID");e=CloseCommands.change(e,"recordVersion","2");e=CloseCommands.change(e,"paymentPresent",true);}return new Trade(e,p);}
  public Result complete(Completion c){completeCalls++;c.validate(roster(c.teamId()).members());var prior=completed.putIfAbsent(c.teamId(),c);check(prior==null||prior.equals(c),"same completionId/checkedAt/complete facts on retry");for(var d:c.results())if(d.disposition().equals("CLOSED_UNPAID"))check(trades.delegate.requests.get(d.outTradeNo()).closeId().equals(d.closeId()),"A validates original closeId");states.put(c.teamId(),"FAILED");if(lost){lost=false;throw new IllegalStateException("owned commit then response loss");}return new Result(c.teamId(),c.reconciliationId(),"FAILED","9",PaymentService.time(System.currentTimeMillis()));}
 }
 private static long count(JdbcTemplate db,String q,Object...a){return db.queryForObject(q,Long.class,a);}
 private static String task(JdbcTemplate db,MarketOrder o){String id=id();db.update("INSERT INTO b_reconciliation_task(task_id,source,channel,team_id,next_attempt_ms,created_at_ms,updated_at_ms) VALUES(?,'s01','c01',?,0,0,0)",id,o.evidence().teamId());return id;}
 private static void due(JdbcTemplate db,String task){db.update("UPDATE b_reconciliation_task SET next_attempt_ms=0 WHERE task_id=?",task);}
 private static void drive(ReconciliationService service,JdbcTemplate db,String task,int rounds){for(int i=0;i<rounds;i++){due(db,task);for(String order:db.queryForList("SELECT out_trade_no FROM b_reconciliation_member WHERE task_id=?",String.class,task))db.update("UPDATE b_trade_coordination SET next_attempt_ms=0,lease_until_ms=IF(lease_token IS NULL,NULL,0) WHERE order_id=?",order);service.recover(task);}}
 private static void held(JdbcTemplate db,String order){check(count(db,"SELECT COUNT(*) FROM b_inventory_reservation WHERE order_id=? AND state='HELD'",order)==1&&count(db,"SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",order)==1,"unknown/paid keeps HELD and original guard");}
 static void payOwned(org.springframework.context.ConfigurableApplicationContext ctx,IPaymentRepository pay,ISimulatedChannel channel,String actor,String payment){var w=pay.claim(payment);check(w!=null,"owned payment task");var p=pay.payment(actor,payment);var a=pay.attempt(payment,w.attemptId());var o=pay.order(actor,p.orderId());long before=pay.now();var evidence=ctx.getBean(ITradePort.class).execute(new TradeDispatch(null,o,"query",id(),null)).evidence();var ev=new Evidence(evidence,before,pay.now(),1000000,2000,2000,2000);var fact=channel.query(payment,a.attemptId());if(fact==null)fact=channel.create(p,a,o,ev);if(w.action().equals("CHOOSE_RESULT"))fact=channel.choose(p,a,o,ev,w.result());pay.finish(w,fact);}
 public static int run(String mode){try{
  check(Set.of("verify","recover").contains(mode)&&env("B_DATABASE_SCOPE").equals("b02-test")&&env("B_DATABASE_USERNAME").equals("zj_market_b02_test_app"),"exact isolated B scope");var dir=Path.of(env("B_PAYMENT_WORK"));Files.createDirectories(dir);
  try(var ctx=new SpringApplication(Config.class,OrderCommands.ProbeConfiguration.class,ZjMarketApplication.class).run("--server.port=0","--b.identity.enabled=true","--b.product.enabled=true","--b.inventory.enabled=true","--b.order.enabled=true","--b.trade.enabled=true","--b.trade.scheduler-enabled=false","--b.payment.enabled=true","--b.payment.checkout-enabled="+mode.equals("verify"),"--b.payment.scheduler-enabled=false","--b.trade.events-enabled=false","--b.trial.enabled=false","--b.sync.enabled=false","--b.infrastructure.database.enabled=true","--b.infrastructure.rpc.enabled=false","--b.infrastructure.mq.enabled=false")){
   var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var orders=ctx.getBean(IOrderRepository.class);var trade=ctx.getBean(TradeRepository.class);var closer=ctx.getBean(ITradeCoordinationService.class);var pay=ctx.getBean(IPaymentRepository.class);var payments=ctx.getBean(IPaymentService.class);var channel=ctx.getBean(ISimulatedChannel.class);var settlement=new SettlementRepository(ds,tx,orders,"zj-market","s01","c01");var blocks=new OrderReviewBlocks(db);settlement.enableReconciliation(blocks);var closing=new PaymentClosingRepository(ds,tx,orders,(IChannelClosing)channel,settlement);trade.enablePaymentClosing(closing);trade.enableReconciliation(blocks::canRecover);var repo=new ReconciliationRepository(ds,tx,orders,trade,closer,"s01","c01");repo.validateSchema();var probe=new Probe(ctx.getBean(PaymentClosingCommands.Probe.class));var service=new ReconciliationService(repo,probe,(IChannelFacts)channel,settlement);
   if(mode.equals("recover")){var saved=JSON.readTree(Files.readAllBytes(dir.resolve("restart.json")));String task=saved.path("task").asText();var row=db.queryForMap("SELECT * FROM b_reconciliation_task WHERE task_id=?",task);var roster=JSON.readValue((byte[])row.get("roster"),Roster.class);String team=row.get("team_id").toString();probe.rosters.put(team,roster);probe.states.put(team,"FAILED");for(var m:roster.members()){var o=orders.byId(m.userId(),m.outTradeNo());probe.trades.delegate.records.put(o.orderId(),o.evidence());if(m.payment()!=null)probe.paid.put(m.outTradeNo(),m.payment());}var request=JSON.readValue((byte[])db.queryForMap("SELECT request FROM b_reconciliation_submission WHERE task_id=?",task).get("request"),Completion.class);probe.completed.put(team,request);drive(service,db,task,5);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND state='RESOLVED'",task)==1,"new JVM resumes unknown original completion");check(saved.path("hash").asText().equals(db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,task)),"original completion bytes/hash across JVM");check(count(db,"SELECT COUNT(*) FROM b_refund WHERE order_id=? AND eligibility_status='ELIGIBLE' AND funds_status='NONE'",saved.path("order").asText())==1,"new JVM transfers one paid obligation, does not execute refund");held(db,saved.path("order").asText());Files.writeString(dir.resolve("recover.txt"),"status=PASSED\nnew-JVM/checkout-disabled/original-completion/hash/one-refund/HELD=PASSED\n");return 0;}
   var identity=ctx.getBean(IIdentityService.class);String suffix=id().substring(0,8),password="Recon-"+id();var u=identity.register("rcu"+suffix,password,"recon user");var op=identity.initializeOperator("rco"+suffix,password,"recon op");String actor=u.userId();
   // Never-opened unpaid closes through original A close/query, then one complete batch.
   var unpaid=PaymentCommands.fresh(ctx,actor,op.userId());String t=task(db,unpaid);probe.roster(unpaid.evidence().teamId());drive(service,db,t,1);
   // Frozen probe windows can be short on NEW orders; historical records are not altered.
   probe.trades.delegate.reserveLifetime=400;var shortUnpaid=PaymentCommands.fresh(ctx,actor,op.userId());probe.trades.delegate.reserveLifetime=900000;String st=task(db,shortUnpaid);Thread.sleep(500);drive(service,db,st,10);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND state='RESOLVED'",st)==1&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",shortUnpaid.orderId())==1,"unpaid original-close full reconciliation releases once");
   // Paid before deadline, notification first observed by reconciliation; A acceptance is separately queried.
   probe.trades.delegate.reserveLifetime=7000;var paidOrder=PaymentCommands.fresh(ctx,actor,op.userId());probe.trades.delegate.reserveLifetime=900000;var accepted=payments.create(actor,paidOrder.orderId(),id(),null,id());String payment=accepted.receipt().paymentId(),attempt=accepted.receipt().attemptId();payOwned(ctx,pay,channel,actor,payment);payments.choose(actor,payment,attempt,id(),"SUCCEEDED",id());payOwned(ctx,pay,channel,actor,payment);var channelFact=((IChannelFacts)channel).fact(payment,attempt);probe.paid.put(paidOrder.orderId(),new Paid(payment,channelFact.channel().amount(),"CNY",PaymentService.time(channelFact.channel().paidAt())));long remaining=ReservationEvidence.instant(paidOrder.evidence().paymentDeadline())-System.currentTimeMillis()+20;if(remaining>0)Thread.sleep(remaining);String pt=task(db,paidOrder);probe.lost=true;drive(service,db,pt,3);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND state='SUBMIT_UNKNOWN'",pt)==1,"A commit/response loss stays unknown with frozen request");held(db,paidOrder.orderId());check(count(db,"SELECT COUNT(*) FROM b_trade_outbox WHERE payment_id=?",payment)==1,"original deadline payment produces exactly one original Outbox");String frozenHash=db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,pt);
   // Only this new owned channel attempt is faulted, after a real short deadline.
   probe.trades.delegate.reserveLifetime=7000;var outside=PaymentCommands.fresh(ctx,actor,op.userId());probe.trades.delegate.reserveLifetime=900000;var oc=payments.create(actor,outside.orderId(),id(),null,id());String opay=oc.receipt().paymentId(),oa=oc.receipt().attemptId();payOwned(ctx,pay,channel,actor,opay);payments.choose(actor,opay,oa,id(),"SUCCEEDED",id());payOwned(ctx,pay,channel,actor,opay);long od=ReservationEvidence.instant(outside.evidence().paymentDeadline());long ow=od-System.currentTimeMillis()+20;if(ow>0)Thread.sleep(ow);db.update("UPDATE b_sim_attempt SET paid_at_ms=? WHERE payment_id=? AND attempt_id=?",od+1,opay,oa);String ot=task(db,outside);probe.lost=true;drive(service,db,ot,3);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE order_id=? AND eligibility_status='WAITING_ELIGIBILITY' AND funds_status='NONE'",outside.orderId())==1&&count(db,"SELECT COUNT(*) FROM b_trade_outbox WHERE payment_id=?",opay)==0,"outside money persists stable refund before completion without normal payment Outbox");held(db,outside.orderId());String outsideHash=db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,ot);drive(service,db,ot,3);check(count(db,"SELECT COUNT(*) FROM b_refund WHERE order_id=? AND eligibility_basis='OUTSIDE_WINDOW_RESOLVED' AND eligibility_status='ELIGIBLE' AND funds_status='NONE'",outside.orderId())==1&&outsideHash.equals(db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,ot)),"outside declaration becomes eligible only after original completion replay ACK");held(db,outside.orderId());
   // A cancellation after an in-window channel success cannot be relabelled outside/unpaid.
   var cancelled=PaymentCommands.fresh(ctx,actor,op.userId());var cc=payments.create(actor,cancelled.orderId(),id(),null,id());String cp=cc.receipt().paymentId(),ca=cc.receipt().attemptId();payOwned(ctx,pay,channel,actor,cp);payments.choose(actor,cp,ca,id(),"SUCCEEDED",id());payOwned(ctx,pay,channel,actor,cp);var ce=probe.trades.delegate.records.get(cancelled.orderId());probe.trades.delegate.records.put(cancelled.orderId(),CloseCommands.change(ce,"orderStatus","CANCELLED"));String ctask=task(db,cancelled);drive(service,db,ctask,4);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND state='REVIEW_REQUIRED'",ctask)==1&&count(db,"SELECT COUNT(*) FROM b_reconciliation_submission WHERE task_id=?",ctask)==0,"in-window paid/A CANCELLED isolated with no fabricated declaration");check(count(db,"SELECT COUNT(*) FROM b_payment WHERE payment_id=? AND funds_state='SUCCEEDED'",cp)==1&&count(db,"SELECT COUNT(*) FROM b_refund WHERE order_id=? AND eligibility_status='ELIGIBLE'",cancelled.orderId())==0&&count(db,"SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",cancelled.orderId())==0,"cancelled anomaly retains original payment and prohibits blind refund/release");held(db,cancelled.orderId());B05Conservation.capture(db,List.of(cancelled.orderId()),dir,"cancelled-in-window-isolation");
   // Complete roster cannot silently omit a member absent from B.
   var missing=PaymentCommands.fresh(ctx,actor,op.userId());String mt=task(db,missing);var original=probe.roster(missing.evidence().teamId());var more=new ArrayList<>(original.members());more.add(new Member("missing-user",id(),id(),"RESERVED",original.members().getFirst().reservedAt(),original.members().getFirst().paymentDeadline(),"9.00","CNY",null));probe.rosters.put(missing.evidence().teamId(),new Roster(original.reconciliationId(),original.rosterVersion(),"RECONCILING","3",original.validEndTime(),more));drive(service,db,mt,4);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_submission WHERE task_id=?",mt)==0&&count(db,"SELECT COUNT(*) FROM b_reconciliation_member WHERE task_id=? AND state='MISSING_LOCAL'",mt)==1,"missing local member visible and no partial submission");held(db,missing.orderId());
   // Real row locks cross lease expiry. No mock DB clock is used.
   for(boolean replace:List.of(false,true)){var lockOrder=PaymentCommands.fresh(ctx,actor,op.userId());String lt=task(db,lockOrder);var lease=repo.claim(lt);db.update("UPDATE b_reconciliation_task SET lease_until_ms="+"CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)"+"+150 WHERE task_id=?",lt);try(var connection=ds.getConnection()){connection.setAutoCommit(false);try(var statement=connection.prepareStatement("SELECT task_id FROM b_reconciliation_task WHERE task_id=? FOR UPDATE")){statement.setString(1,lt);statement.executeQuery().close();}try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var waiting=executor.submit(()->repo.defer(lease,"OWNED_STALE_WRITE",false));Thread.sleep(80);check(!waiting.isDone(),"actual SQL row lock blocks old writeback");Thread.sleep(200);if(replace)try(var statement=connection.prepareStatement("UPDATE b_reconciliation_task SET lease_token='replacement',lease_until_ms=CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)+30000 WHERE task_id=?")){statement.setString(1,lt);statement.executeUpdate();}connection.commit();waiting.get(5,TimeUnit.SECONDS);}}check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND last_error='OWNED_STALE_WRITE'",lt)==0,"lock-after-time lease/token fencing");held(db,lockOrder.orderId());}
   // Only owned temporary blocks clear on a concurrent COMPLETED observation.
   var complete=PaymentCommands.fresh(ctx,actor,op.userId());String ct=task(db,complete);drive(service,db,ct,2);probe.states.put(complete.evidence().teamId(),"COMPLETED");drive(service,db,ct,1);check(!orders.byId(actor,complete.orderId()).reviewRequired()&&count(db,"SELECT COUNT(*) FROM b_refund WHERE order_id=?",complete.orderId())==0,"last payment terminal completion clears own block without refund");held(db,complete.orderId());
   var legacy=PaymentCommands.fresh(ctx,actor,op.userId());db.update("UPDATE b_market_order SET review_required=TRUE,last_error='TEAM_RECONCILIATION_REQUIRED' WHERE order_id=?",legacy.orderId());String lt=task(db,legacy);drive(service,db,lt,2);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND state='REVIEW_REQUIRED'",lt)==1&&orders.byId(actor,legacy.orderId()).reviewRequired(),"unclassified legacy review is not silently cleared");held(db,legacy.orderId());
   // Marketplace rollbacks restore roster and member rows together.
   var rollback=PaymentCommands.fresh(ctx,actor,op.userId());String rt=task(db,rollback);var rl=repo.claim(rt);var rollbackTeam=probe.team(rollback.evidence().teamId());var rollbackRoster=probe.roster(rollback.evidence().teamId());tx.executeWithoutResult(status->{repo.saveRoster(rl,rollbackTeam,rollbackRoster);status.setRollbackOnly();});check(count(db,"SELECT COUNT(*) FROM b_reconciliation_member WHERE task_id=?",rt)==0&&count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE task_id=? AND roster IS NULL",rt)==1,"roster/member writes roll back atomically");
   repo.discover(20);check(count(db,"SELECT COUNT(*) FROM b_reconciliation_task WHERE team_id=?",outside.evidence().teamId())==1,"discovery deduplicates existing team and links original evidence in bounded batches");
   Files.writeString(dir.resolve("restart.json"),JSON.writeValueAsString(Map.of("task",pt,"order",paidOrder.orderId(),"hash",frozenHash)));Files.writeString(dir.resolve("verify.txt"),"status=PASSED\nreal-MySQL/controlled-A/no-runtime-fault-HTTP=PASSED\nunpaid-original-close/one-RELEASE/paid-before-deadline/original-Outbox=PASSED\nfull-roster/missing-local/no-partial-submit/commit-response-loss=PASSED\nactual-row-lock-expiry/replaced-token/rollback/owned-block/legacy-review=PASSED\nchannel-success/A-CANCELLED/no-fabricated-unpaid-or-outside/no-blind-refund/HELD=PASSED\noutside-window/stable-refund-before-submit/no-normal-payment-Outbox/original-replay-eligibility=PASSED\nrefund=obligation-only-NONE; no refund execution\nrestart=PREPARED\n");return 0;
  }
 }catch(Exception e){try{Files.writeString(Path.of(env("B_PAYMENT_WORK")).resolve("failure-"+mode+".txt"),e.toString()+"\n"+Arrays.toString(e.getStackTrace()));}catch(Exception ignored){}System.err.println("Reconciliation verification failed: "+e.getClass().getSimpleName());return 1;}}
}
